codeExample.bad:
/* Fixed-height card with clipped overflow: fine at 100%, but at 200% zoom
   the enlarged text no longer fits and the overflow is hidden, silently
   cutting off the end of the description. */
.product-card {
  width: 320px;
  height: 140px;
  overflow: hidden;
}
.product-card__description {
  font-size: 14px;
  line-height: 1.4;
}

codeExample.good:
/* No fixed height and no overflow: hidden, so the card grows to fit
   whatever size the text becomes at any zoom level. A min-height keeps
   the card from looking too small at 100% without capping it. */
.product-card {
  width: 320px;
  min-height: 140px;
}
.product-card__description {
  font-size: 14px;
  line-height: 1.4;
}
